wallalertruleresponse.query:
label_replace(
(
  probe_success{pingip=~".*:9090"}
),
 "pingip",
 "$1",
 "pingip",
 "(.*):.*"
)
/ on (pingip) group_left() probe_success{pingip=~".*", job="cube-blackbox"}

label_replace(
(
  probe_success{pingip=~".*:8080"}
),
 "pingip",
 "$1",
 "pingip",
 "(.*):.*"
)
/ on (pingip) group_left() probe_success{pingip=~".*", job="ccvm-blackbox"}

(libvirt_domain_fs_info_usage_bytes{domain!~"r-.*|s-.*|v-.*|ccvm|scvm"}
/
on (instance, domain, partition_mountpoint, partition_name, partition_type, serial)
libvirt_domain_fs_info_total_bytes{domain!~"r-.*|s-.*|v-.*|ccvm|scvm", partition_mountpoint!~"System Reserved|/boot"}
) * 100
* on (instance, serial)
group_left(display_volume_name, mold_volume_type)
libvirt_domain_block_meta{domain!~"r-.*|s-.*|v-.*|ccvm|scvm", serial!=""}
* on (instance, domain)
group_left(domain_mold_name, display_mold_name, vm_user_name)
libvirt_domain_info_meta{domain!~"r-.*|s-.*|v-.*|ccvm|scvm"}
